-- ============================================================
--  bladeball-ledger : โครงฐานข้อมูลฝั่ง Postgres (Supabase)
--
--  ไฟล์นี้คือ "ตัวจริง" ตั้งแต่ 26 ก.ย. 2026
--  ส่วน schema.sql (SQLite) เก็บไว้ใช้ตอนรันเทสต์แบบไม่ต้องต่อเน็ต
--  มีเทสต์ใน tests/smoke.py คุมไว้ว่าสองไฟล์ต้องมีตาราง/คอลัมน์ตรงกัน
--
--  สิ่งที่ต่างจาก SQLite และ *เหตุผล*
--
--  1) id ใช้ GENERATED BY DEFAULT AS IDENTITY
--     Postgres ไม่ได้แจกเลขให้เองเหมือน SQLite ต้องบอกให้ชัด
--     ที่ใช้ BY DEFAULT (ไม่ใช่ ALWAYS) เพราะตอนย้ายข้อมูลเก่าเข้ามา
--     ต้องใส่ id เดิมทับลงไปให้ตรงกับของเดิม
--
--  2) วันที่ใช้ date / เวลาใช้ timestamptz ไม่ใช่ TEXT
--     ของเดิมเป็นข้อความ ฐานข้อมูลเลยไม่รู้ว่ามันคือวันที่
--     ใส่ '2026-13-45' ก็ยังผ่าน และเรียงเดือนข้ามปีพลาดได้
--     พอเป็น date จริง ฐานข้อมูลปฏิเสธวันที่ไม่มีอยู่จริงให้เลย
--     ฝั่ง Python ยังเห็นเป็นข้อความ 'YYYY-MM-DD' เหมือนเดิม
--     เพราะ src/store.py แปลงกลับให้ (บอทจึงไม่ต้องแก้)
--
--  3) เงินใช้ numeric ไม่ใช่ REAL
--     REAL คือทศนิยมลอยตัว บวกเลขเงินหลายครั้งแล้วเพี้ยนได้
--     (0.1 + 0.2 ไม่เท่ากับ 0.3 เป๊ะ) ยอดเงินต้องเป๊ะเพราะต้องตรงกับกรุงไทย
--     numeric เก็บเป็นเลขฐานสิบจริง บวกกี่ครั้งก็ไม่เพี้ยน
--
--  4) VIEW ใส่ NULLIF(...,0) กันตัวหารเป็นศูนย์
--     SQLite หารศูนย์แล้วได้ NULL เฉยๆ แต่ Postgres ฟ้อง error
--     ถ้าไม่กันไว้ วันไหนมีออเดอร์ tokens_spent = 0 หลุดเข้ามา
--     VIEW จะพังทั้งตัว รายงานทุกคำสั่งจะใช้ไม่ได้ทันที
-- ============================================================


-- ------------------------------------------------------------
--  sale : 1 แถว = 1 ออเดอร์ (ไม่ใช่ 1 ชิ้น)
--
--  ทำไมไม่เก็บ "ชื่อไอเทม" เป็นตัวหลัก ?
--  ไอเทมในเกมมีเป็นหมื่นชิ้น แทบไม่ซ้ำกันเลย ถ้าเก็บชื่อแล้วเอาไป
--  group by จะได้กลุ่มละ 1 แถว วิเคราะห์อะไรไม่ได้
--  เลยเก็บ "คุณสมบัติที่ซ้ำได้" แทน คือ จำนวน Token / ประเภท / กลุ่มลูกค้า
--  ส่วนชื่อไอเทมเก็บไว้ใน note เผื่ออยากย้อนดู แต่ไม่ใช้วิเคราะห์
-- ------------------------------------------------------------
--  เคยมีคอลัมน์ category / fb_group / customer_ref / list_baht ตรงนี้
--  ถอดออก 27 ก.ย. 2026 เพราะจดมา 89 ออเดอร์ ไม่มีใครใส่เลยสักครั้ง (0%)
--
--  สาเหตุไม่ใช่ขี้เกียจ แต่ขัดกับข้อกำหนดข้อแรกคือ "จดให้เร็วที่สุด"
--  พิมพ์ 55 192 ใช้ 2 วินาที · พิมพ์ 55 192 ดาบ a ใช้ 5 วินาที
--  คูณ 89 ครั้ง ความเร็วชนะทุกครั้ง และมันควรชนะ
--  เพราะถ้าจดช้าจนเลิกจด ข้อมูลจะเป็นศูนย์
--
--  บทเรียน: ช่องที่ไม่มีใครกรอก แย่กว่าไม่มีช่อง
--  เพราะทำให้เข้าใจผิดว่าวิเคราะห์ได้ทั้งที่วิเคราะห์ไม่ได้
--  เหลือมิติเดียวที่ใช้จริงคือ token_band ซึ่งคำนวณจาก tokens_spent เอง
--  ไม่ต้องพิมพ์อะไรเพิ่ม
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS sale (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sold_on       date          NOT NULL,          -- วันทำการ
    logged_at     timestamptz   NOT NULL,          -- เวลาที่กดบันทึกจริง
    price_baht    numeric(12,2) NOT NULL,          -- เงินที่ได้รับจริง
    tokens_spent  INTEGER       NOT NULL,          -- Token ที่กดจ่ายจากบูธจริง
                                                   -- ไม่ใช่ Your Value (RAP) ซึ่งต่ำกว่า 2-4%
    token_rate    numeric(8,3)  NOT NULL,          -- Token ต่อ 1 บาท (11 / 10.5 / 10 / ของร้อน ~20)
    source        TEXT          NOT NULL DEFAULT 'seller'
                                CHECK (source IN ('seller','hot_lot')),
    item_count    INTEGER       NOT NULL DEFAULT 1,
    account       TEXT NOT NULL DEFAULT 'ktb',   -- เงินเข้า/ออกบัญชีไหน
    note          TEXT
);

CREATE INDEX IF NOT EXISTS idx_sale_sold_on ON sale (sold_on);


-- ------------------------------------------------------------
--  day_log : 1 แถว = 1 วัน
--
--  ตารางนี้คือหัวใจของโจทย์ "วันที่ไม่มีรายได้เกิดจากอะไร"
--  ถ้ามีแต่ตาราง sale เราจะแยกไม่ออกเลยว่าวันที่ไม่มีแถว แปลว่า
--    - ไม่ได้เปิดร้าน
--    - เปิดแล้วแต่ไม่มีคนทัก
--    - มีคนทักแต่ปิดการขายไม่ได้
--    - ขายได้แต่ลืมจด
--  ทั้ง 4 อย่างนี้แก้คนละวิธี จึงต้องบันทึกแยกให้ชัด
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS day_log (
    log_date       date PRIMARY KEY,
    shop_open      INTEGER,                        -- 1 = เปิดร้าน, 0 = ไม่ได้เปิด
    no_sale_reason TEXT CHECK (no_sale_reason IN
                       ('not_open','no_inquiry','no_close','forgot') OR no_sale_reason IS NULL),
    inquiries      INTEGER,                        -- จำนวนคนทัก (ถ้าจดไหว)
    note           TEXT
);


-- ------------------------------------------------------------
--  purchase : ทุกบาทที่จ่ายออกไปเพื่อเอาของมาขาย
--
--  ของเข้าร้านมี 2 ทาง และสองทางนี้ไม่เหมือนกันเลย
--
--  1) kind='token'  ซื้อ Token จากพ่อค้า
--     จ่ายเงิน แล้วได้ Token ทันที เอาไปกดซื้อของที่ลูกค้าอยากได้
--     ได้ของแน่นอน รู้เรทตั้งแต่วินาทีแรก
--
--  2) kind='lot'    รับ "เหมา" มาย่อยเอง
--     จ่ายเงิน แล้วได้ "ไอเทม" ไม่ใช่ Token
--     ต้องเอาไปตั้งบูธขายก่อน Token ถึงจะเข้าตัว
--     เรทบนกระดาษดีกว่ามาก (17-25 เทียบกับ 11) แต่:
--       - ต้องรอให้มีคนมาซื้อจากบูธ
--       - บูธกินค่าธรรมเนียม 1%
--       - ชิ้นที่ขายไม่ออกเลย = เงินจม  <-- ความเสี่ยงตัวจริง
--     rap_total คือ RAP รวมตอนได้มา ส่วน tokens_realised คือ Token ที่ได้จริง
--     ผลต่างสองอันนี้คือราคาของความเสี่ยงที่ต้องจ่ายเพื่อแลกกับเรทที่ดีกว่า
--
--     ค่าธรรมเนียมบูธ: ได้ = floor(ราคาที่ตั้ง x 0.99)
--     วัดจากในเกมจริง — ตั้ง 17 ได้ 16 · ตั้ง 20 ได้ 19 · ตั้ง 40,000 ได้ 39,600
--     เจ้าของจึงตั้งราคาสูงกว่า RAP นิดหน่อยเพื่อให้ได้ RAP กลับมาครบ
--     ไม่ได้ตั้งใจเอากำไรจากบูธ เพราะกำไรมาจากตอนรับเหมาถูกอยู่แล้ว
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS purchase (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    bought_on       date          NOT NULL,
    logged_at       timestamptz   NOT NULL,
    kind            TEXT          NOT NULL CHECK (kind IN ('token','lot')),
    baht            numeric(12,2) NOT NULL,      -- เงินที่จ่ายออกไปจริง
    tokens          INTEGER,                     -- kind='token' : Token ที่ได้มาเลย
    rap_total       INTEGER,                     -- kind='lot'   : RAP รวมของทั้งชุด
    tokens_realised INTEGER,                     -- kind='lot'   : ย่อยขายได้จริงเท่าไหร่ (เติมทีหลัง)
    item_count      INTEGER,
    account         TEXT NOT NULL DEFAULT 'ktb',  -- จ่ายจากบัญชีไหน
    note            TEXT
);

CREATE INDEX IF NOT EXISTS idx_purchase_bought_on ON purchase (bought_on);


-- ------------------------------------------------------------
--  token_move : Token ที่เข้า-ออก โดยไม่ใช่การขายให้ลูกค้าหรือซื้อจากพ่อค้า
--
--  ตอนแรกไม่มีตารางนี้ แล้วพบว่ายอด Token ตรวจไม่ตรงเลย เพราะวันจริงมี
--    - ขายของตัวเองที่บูธได้ Token เข้ามา (เช่น ขายปืนได้ 670)
--    - ซื้อของให้ลูกค้าเก่าที่ไม่ได้อยู่ในออเดอร์วันนั้น (เช่น 46)
--    - ยอดยกมาตอนเริ่มใช้ระบบ
--  ทั้งหมดนี้ไม่มีเงินบาทเข้าออก แต่กระทบยอด Token เต็มๆ
--
--  kind='adjust' คือส่วนต่างที่บอทบันทึกให้เองตอนสั่ง /เช็ค
--  ส่วนใหญ่มาจากการกดซื้อของที่บูธแพงกว่า RAP ซึ่งวัดได้แค่ทางอ้อม
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS token_move (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    happened_on date        NOT NULL,
    logged_at   timestamptz NOT NULL,
    tokens      INTEGER     NOT NULL,      -- บวก = เข้า, ลบ = ออก
    kind        TEXT        NOT NULL
                CHECK (kind IN ('open','booth_in','other_out','adjust')),
    note        TEXT
);

CREATE INDEX IF NOT EXISTS idx_token_move_on ON token_move (happened_on);


-- ------------------------------------------------------------
--  spend : รายจ่ายส่วนตัว (ค่าข้าว ค่าเที่ยว) — เงินคนละก้อนกับธุรกิจ
--
--  ตารางนี้ต้องไม่ถูก join เข้ากับ v_sale / v_day / การคิดกำไรใดๆ ทั้งสิ้น
--
--  กฎในชีตการเงินเขียนไว้ว่า "ห้ามเอาเงินการค้ากับเงินส่วนตัวไว้บัญชีเดียวกัน"
--  ซึ่งหมายถึงบัญชีธนาคาร (กรุงไทย = การค้า · K-eSavings = ส่วนตัว)
--  จดไว้ในฐานข้อมูลเดียวกันได้ แต่ห้ามเอามาบวกกันเด็ดขาด
--  ไม่งั้นคำว่า "กำไร" จะไม่มีความหมาย และสูตร ยอดกรุงไทย - 1,000 จะพัง
--
--  category เป็นข้อความอิสระ ไม่ได้บังคับค่า เพราะเป็นหมวดของเจ้าของเอง
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS spend (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    spent_on  date          NOT NULL,
    logged_at timestamptz   NOT NULL,
    baht      numeric(12,2) NOT NULL,
    category  TEXT,
    note      TEXT
);

CREATE INDEX IF NOT EXISTS idx_spend_on ON spend (spent_on);


-- ------------------------------------------------------------
--  transfer : เงินที่ย้ายออกจากบัญชีร้าน (กรุงไทย) ไปที่อื่น
--
--  ทำไมต้องมีตารางนี้
--  ก.ย. 2026 เจอปัญหาว่ากรุงไทยเหลือ 100 บาท แล้วบอทรายงานว่า
--  "เก็บเงินได้ 0 บาท" ทั้งที่เดือนนั้นกำไร 9,682 บาท
--  เพราะเงินถูกย้ายไป Dime 5,600 และ K-bank อีกราว 4,600 แล้ว
--  แต่ไม่มีที่จดว่าย้ายไป บอทจึงเข้าใจว่าเงินหายไปเฉยๆ
--
--  ⚠️ การย้ายเงินไม่ใช่รายจ่าย และไม่ทำให้กำไรลดลง
--  เงินยังเป็นของเจ้าของอยู่ แค่ย้ายกระเป๋า
--  ตารางนี้จึงห้ามถูก join เข้ากับการคิดกำไร เหมือนตาราง spend
--  หน้าที่เดียวของมันคืออธิบายว่า "ทำไมยอดกรุงไทยไม่เท่ากับกำไร"
--
--  baht เป็นบวก = ออกจากบัญชีร้าน  ·  เป็นลบ = เอาเงินนอกใส่เข้าร้าน
--  (เคสติดลบเกิดจริงตอนเงินร้านไม่พอซื้อ Token แล้วควักเงินตัวเองใส่)
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS transfer (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    moved_on    date          NOT NULL,
    logged_at   timestamptz   NOT NULL,
    baht        numeric(12,2) NOT NULL,
    destination TEXT,                      -- ปลายทาง เช่น dime, หุ้น, kbank
    note        TEXT
);

CREATE INDEX IF NOT EXISTS idx_transfer_on ON transfer (moved_on);

-- ------------------------------------------------------------
--  pending_order : ลูกค้าโอนเงินมาแล้ว แต่ยังไม่ได้ส่งของ
--
--  ทำไมต้องมี
--  flow จริงคือ ลูกค้าโอนก่อน -> ไปกดซื้อของ -> ส่งให้
--  ระหว่างนั้นมีช่องว่าง (คูลดาวน์เทรด 15 นาที + เวลารีเฟรชหาของ)
--  ปกติจบใน 1 ชั่วโมง แต่มีเคสที่ค้างข้ามวันหรือค้างถาวร
--  ก.ย. 2026 เจอเคสจริง — ลูกค้าโอน 750 บาทแล้วหายไปเลย ไม่มารับของ
--
--  ถ้าไม่มีตารางนี้ เงินที่รับมาแล้วยังไม่ได้ส่งของจะถูกนับเป็นกำไรทันที
--  ทั้งที่ยังติดหนี้ของอยู่ ถ้าสิ้นเดือนมีค้าง 5 ออเดอร์
--  กำไรที่รายงานจะสูงเกินจริงโดยไม่มีอะไรเตือน
--
--  outcome บอกว่าจบยังไง
--    NULL        ยังค้างอยู่ ยังไม่ได้ส่ง
--    delivered   ส่งของแล้ว (ต้องไปจดเป็นรายการขายปกติด้วย)
--    refunded    คืนเงินไปแล้ว
--    forfeited   ลูกค้าหายไปเลย ตัดสินใจนับเป็นรายได้
--
--  ⚠️ ตารางนี้ห้าม join เข้ากับการคิดกำไร เหมือน spend กับ transfer
--  เงินในนี้ยังไม่ใช่กำไร เพราะยังไม่ได้ส่งของ
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS pending_order (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    received_on date NOT NULL,
    logged_at   timestamptz NOT NULL,
    baht        numeric(12,2) NOT NULL,
    note        TEXT,
    closed_on   date,
    outcome     TEXT CHECK (outcome IN ('delivered','refunded','forfeited')
                            OR outcome IS NULL)
);

CREATE INDEX IF NOT EXISTS idx_pending_open ON pending_order (outcome);

-- ------------------------------------------------------------
--  expense : ต้นทุนของธุรกิจที่ไม่ใช่ของเข้าร้าน
--
--  ทำไมต้องแยกจากอีก 3 ตาราง
--    purchase  = ของเข้าร้าน ต้องมี Token หรือ RAP ตามมาด้วย
--    spend     = เงินส่วนตัว ห้ามแตะกำไรธุรกิจ
--    transfer  = ย้ายกระเป๋า เงินยังเป็นของเรา ไม่ใช่ต้นทุน
--  ค่าธรรมเนียมโอนเงินไม่เข้าพวกไหนเลย แต่เป็นต้นทุนจริงที่ต้องหักจากกำไร
--
--  เจอ 27 ก.ย. 2026 — ทรูมันนี่หักค่าธรรมเนียม 25 บาทตอนดึงเงินเข้าธนาคาร
--  เพราะใช้เกินโควตาฟรีของเดือน  ออเดอร์นั้นรับมา 60 บาท
--  ค่าธรรมเนียมกินไป 42% ของรายรับ และ 65% ของกำไร
--
--  ⚠️ ค่าธรรมเนียมแบบนี้การกระทบยอดธนาคารจับไม่ได้
--  เพราะหักจากยอดในวอลเล็ท ไม่ได้หักจากบัญชีกรุงไทย
--  กรุงไทยยังได้รับเงินเต็มจำนวน ยอดเลยตรงทั้งที่มีเงินหายจริง
--  ถ้าไม่มีตารางนี้ ต้นทุนก้อนนี้จะหายไปจากระบบทั้งหมด
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS expense (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    spent_on  date NOT NULL,
    logged_at timestamptz NOT NULL,
    baht      numeric(12,2) NOT NULL,
    category  TEXT,
    note      TEXT
);

CREATE INDEX IF NOT EXISTS idx_expense_on ON expense (spent_on);



-- ------------------------------------------------------------
--  balance_snapshot : ยอดเงินทุกบัญชีรวมกัน ณ วันหนึ่ง
--
--  ทำไมต้องมี
--  27 ก.ย. 2026 ต้องไล่ย้อนหาว่าเงินเริ่มต้นมีเท่าไหร่ ใช้เวลาเป็นชั่วโมง
--  ไล่ผิด 3 รอบ เพราะไม่เคยจดไว้ว่าวันเริ่มต้นมีเงินเท่าไหร่ในแต่ละบัญชี
--  ต้องเดาย้อนจากยอดปลายทาง ซึ่งเดาผิดได้ง่ายมาก
--
--  จดยอดไว้เดือนละครั้งแค่ครั้งเดียว แล้วสิ้นเดือนจะตรวจได้ทันทีว่า
--    เงินเพิ่มขึ้นจริง  เทียบกับ  กำไรที่บอทคิดได้
--  ต่างกันเท่าไหร่ = ที่ใช้ส่วนตัว + เงินที่ได้มาจากนอกธุรกิจ
--
--  cash_baht คือเงินในทุกบัญชีรวมกัน (กรุงไทย + Dime + หุ้น + K-bank)
--  ไม่รวมของในเกม เพราะของในเกมนับจากตาราง token_move อยู่แล้ว
--  ถ้านับสองที่จะกลายเป็นนับซ้ำ
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS balance_snapshot (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    taken_on  date          NOT NULL,
    logged_at timestamptz   NOT NULL,
    cash_baht numeric(12,2) NOT NULL,
    note      TEXT
);

CREATE INDEX IF NOT EXISTS idx_snapshot_on ON balance_snapshot (taken_on);



-- ------------------------------------------------------------
--  app_state : ค่าที่บอทต้องจำข้ามข้อความ เช่น เรทที่ใช้อยู่ตอนนี้
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS app_state (
    key        TEXT PRIMARY KEY,
    value      TEXT        NOT NULL,
    updated_at timestamptz NOT NULL
);


-- ------------------------------------------------------------
--  job_log : กันบอทส่งข้อความสรุปซ้ำตอนรีสตาร์ท
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS job_log (
    job_key TEXT PRIMARY KEY,                   -- เช่น 'nightly:2026-09-16'
    ran_at  timestamptz NOT NULL
);


-- ============================================================
--  VIEW : คำนวณต้นทุน/กำไรตรงนี้ที่เดียว
--  ห้ามเก็บ profit เป็นคอลัมน์จริง เพราะถ้าแก้ token_rate ย้อนหลัง
--  ตัวเลขจะไม่ตรงกัน — ให้คำนวณสดเสมอ
-- ============================================================
DROP VIEW IF EXISTS v_day;
DROP VIEW IF EXISTS v_sale;
CREATE VIEW v_sale AS
SELECT
    s.id,
    s.sold_on,
    s.logged_at,
    s.price_baht,
    s.tokens_spent,
    s.token_rate,
    s.source,
    s.account,
    s.item_count,
    s.note,

    -- ต้นทุนจริง = Token ที่จ่าย หารด้วยเรทที่ซื้อ Token มา
    ROUND(s.tokens_spent / s.token_rate, 2)                              AS cost_baht,
    ROUND(s.price_baht - s.tokens_spent / s.token_rate, 2)               AS profit_baht,

    -- มาร์จิ้น % ของราคาขาย
    ROUND(100.0 * (s.price_baht - s.tokens_spent / s.token_rate)
          / NULLIF(s.price_baht, 0), 1)                                  AS margin_pct,

    -- ขายได้กี่เท่าของต้นทุน
    ROUND(s.price_baht
          / NULLIF(s.tokens_spent / s.token_rate, 0), 2)                 AS markup_x,

    -- กำไรต่อ Token 1 หน่วยที่ลงไป
    ROUND((s.price_baht - s.tokens_spent / s.token_rate)
          / NULLIF(s.tokens_spent, 0), 4)                                AS profit_per_token,

    -- จัดช่วงราคา Token แทนการ group by ชื่อไอเทม
    CASE
        WHEN s.tokens_spent <  100 THEN '1. ต่ำกว่า 100'
        WHEN s.tokens_spent <  300 THEN '2. 100-299'
        WHEN s.tokens_spent <  600 THEN '3. 300-599'
        WHEN s.tokens_spent < 1500 THEN '4. 600-1499'
        ELSE                            '5. 1500 ขึ้นไป'
    END                                                                  AS token_band
FROM sale s;


-- ------------------------------------------------------------
--  v_purchase : เรทที่คาดไว้ เทียบกับเรทที่ได้จริง
-- ------------------------------------------------------------
DROP VIEW IF EXISTS v_purchase;
CREATE VIEW v_purchase AS
SELECT
    p.*,
    -- เรทที่คาดว่าจะได้
    -- ของเหมาต้องหักค่าธรรมเนียมบูธ 1% ก่อน เพราะยังไงก็ไม่ได้ RAP เต็ม
    CASE WHEN p.kind = 'token' THEN ROUND(p.tokens / NULLIF(p.baht, 0), 2)
         ELSE ROUND(p.rap_total * 0.99 / NULLIF(p.baht, 0), 2) END       AS rate_expected,

    -- RAP ดิบก่อนหักค่าธรรมเนียม — ตัวเลขที่เห็นตอนกดซื้อ
    CASE WHEN p.kind = 'lot'
         THEN ROUND(p.rap_total / NULLIF(p.baht, 0), 2) END              AS rate_on_paper,

    -- เรทที่ได้จริง — ของที่ซื้อเป็น Token ได้เท่าที่เห็นอยู่แล้ว
    -- ส่วนของเหมาต้องรอย่อยขายก่อนถึงจะรู้
    CASE WHEN p.kind = 'token' THEN ROUND(p.tokens / NULLIF(p.baht, 0), 2)
         WHEN p.tokens_realised IS NOT NULL
              THEN ROUND(p.tokens_realised / NULLIF(p.baht, 0), 2) END   AS rate_actual,

    -- ย่อยออกไปได้กี่ % ของที่ "ควรจะได้ถ้าขายหมด"
    -- 100% = ขายหมดทุกชิ้น · ต่ำกว่านั้น = ยังมีของค้างขายไม่ออก
    CASE WHEN p.kind = 'lot' AND p.tokens_realised IS NOT NULL
         THEN ROUND(100.0 * p.tokens_realised / NULLIF(p.rap_total * 0.99, 0), 1)
    END                                                                  AS sold_through_pct
FROM purchase p;


-- ------------------------------------------------------------
--  v_day : รวมยอดรายวัน + เหตุผลของวันที่ไม่มียอด
--  ใช้ day_log เป็นตัวตั้ง เพื่อให้ "วันที่ไม่มีการขาย" ยังมีแถวอยู่
-- ------------------------------------------------------------
CREATE VIEW v_day AS
SELECT
    d.log_date,
    d.shop_open,
    d.no_sale_reason,
    d.inquiries,
    COALESCE(x.orders, 0)        AS orders,
    COALESCE(x.revenue_baht, 0)  AS revenue_baht,
    COALESCE(x.cost_baht, 0)     AS cost_baht,
    COALESCE(x.profit_baht, 0)   AS profit_baht,
    COALESCE(x.tokens_spent, 0)  AS tokens_spent,
    -- อัตราปิดการขาย (ต้องมีตัวเลขคนทักถึงจะคำนวณได้)
    CASE WHEN d.inquiries > 0
         THEN ROUND(100.0 * COALESCE(x.orders,0) / d.inquiries, 1) END AS close_rate_pct
FROM day_log d
LEFT JOIN (
    SELECT sold_on,
           COUNT(*)           AS orders,
           SUM(price_baht)    AS revenue_baht,
           SUM(cost_baht)     AS cost_baht,
           SUM(profit_baht)   AS profit_baht,
           SUM(tokens_spent)  AS tokens_spent
    FROM v_sale
    GROUP BY sold_on
) x ON x.sold_on = d.log_date;
